function setGoodbye(jid, on) { GOODBYE.set(jid, !!on); }
function isGoodbyeOn(jid) { return GOODBYE.get(jid) !== false; }

function setAntispam(jid, on) { ANTISPAM.set(jid, !!on); }
function isAntispamOn(jid) { return !!ANTISPAM.get(jid); }

