function trackAndCheckFlood(jid, userJid) {
  if (!SPAM_TRACK.has(jid)) SPAM_TRACK.set(jid, new Map());
  const userMap = SPAM_TRACK.get(jid);
  const now = Date.now();
  const arr = (userMap.get(userJid) || []).filter((t) => now - t < 7000);
  arr.push(now);
  userMap.set(userJid, arr);
  return arr.length >= 5;
}

